package android.app;import android.service.notification.*;import java.util.*;public class NotificationManager{public static final int IMPORTANCE_HIGH=4;public int posts=0;public boolean enabled=true;Map<String,StatusBarNotification> items=new LinkedHashMap<>();public boolean areNotificationsEnabled(){return enabled;}public void createNotificationChannel(NotificationChannel c){}public void notify(String tag,int id,Notification n){posts++;items.put(tag+":"+id,new StatusBarNotification(tag,id,n));}public void cancel(String tag,int id){items.remove(tag+":"+id);}public void cancel(int id){items.values().removeIf(x->x.id==id);}public StatusBarNotification[] getActiveNotifications(){return items.values().toArray(new StatusBarNotification[0]);}}